<template><section class="authors-space"><header class="authors-head"><div><p>FOLLOWING AUTHORS</p><h2>我关注的旅人 <span>✿</span></h2></div><button type="button" :disabled="loading" @click="load">↻ 刷新</button></header><div v-if="loading" class="state-card">✿ 正在寻找你关注的旅人…</div><div v-else-if="error" class="state-card"><strong>暂时无法读取关注列表</strong><p>{{ error }}</p></div><div v-else-if="!authors.length" class="state-card"><span class="big-heart">♡</span><strong>还没有关注任何旅人</strong><p>去“推荐”里遇见喜欢的作者，关注后会出现在这里。</p></div><div v-else class="author-grid"><article v-for="author in authors" :key="author.id" class="author-card"><button type="button" class="author-main" @click="$emit('open-author',author.id)"><UserAvatar :user-id="author.id" :avatar="author.avatar" :name="author.displayName" :size="82"/><div><p>TRAVEL CREATOR</p><h3>{{ author.displayName }}</h3><span>@{{ author.username }}</span></div></button><div class="author-stats"><span><b>{{ author.publicTravelCount }}</b>公开旅程</span><span><b>{{ author.followerCount }}</b>关注者</span></div><div class="author-actions"><button type="button" class="view" @click="$emit('open-author',author.id)">查看公开旅程 <span>↗</span></button><button type="button" class="unfollow" :disabled="busyId===author.id" @click="unfollow(author)">{{ busyId===author.id?'处理中…':'取消关注' }}</button></div></article></div></section></template>
<script setup lang="ts">
import {onMounted,ref} from 'vue';import UserAvatar from '@/components/UserAvatar.vue';import {followAuthor} from '@/api/social';import {getFollowingAuthorsApi,type FollowedAuthor} from '@/api/profile';defineEmits<{(e:'open-author',id:number):void}>();const authors=ref<FollowedAuthor[]>([]),loading=ref(false),error=ref(''),busyId=ref<number|null>(null);async function load(){if(loading.value)return;loading.value=true;error.value='';try{const r=await getFollowingAuthorsApi();if(r.code!==200)throw new Error(r.message||'读取关注列表失败');authors.value=r.data||[]}catch(e){error.value=e instanceof Error?e.message:'读取关注列表失败'}finally{loading.value=false}}async function unfollow(a:FollowedAuthor){if(busyId.value!=null)return;busyId.value=a.id;try{const r=await followAuthor(a.id,false);if(r.code!==200)throw new Error(r.message||'取消关注失败');authors.value=authors.value.filter(x=>x.id!==a.id)}catch(e){error.value=e instanceof Error?e.message:'取消关注失败'}finally{busyId.value=null}}onMounted(()=>void load())
</script>
<style scoped>.authors-space{padding:18px 0 30px}.authors-head{margin:6px 0 18px;display:flex;align-items:flex-end;justify-content:space-between;gap:14px}.authors-head p{margin:0 0 5px;color:#c5789b;font-size:9px;font-weight:800;letter-spacing:.18em}.authors-head h2{margin:0;color:#79445f;font-size:28px}.authors-head h2 span{color:#d67ca5}.authors-head>button{border:0;border-radius:999px;padding:10px 14px;cursor:pointer;color:#87506c;background:#fff6fa}.author-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.author-card{padding:20px;border:1px solid rgba(255,255,255,.9);border-radius:25px;background:rgba(255,249,252,.73);box-shadow:0 18px 45px rgba(200,102,144,.12);backdrop-filter:blur(18px)}.author-main{width:100%;display:flex;align-items:center;gap:16px;padding:0;border:0;cursor:pointer;text-align:left;background:none}.author-main p{margin:0 0 4px;color:#ca7ca0;font-size:8px;letter-spacing:.14em}.author-main h3{margin:0;color:#77435d;font-size:20px}.author-main span{color:#b18299;font-size:11px}.author-stats{margin:18px 0;display:grid;grid-template-columns:1fr 1fr;gap:8px}.author-stats span{padding:11px;border-radius:14px;color:#a1748c;font-size:10px;text-align:center;background:rgba(255,255,255,.63)}.author-stats b{display:block;color:#844d69;font-size:16px}.author-actions{display:flex;gap:8px}.author-actions button{flex:1;min-height:40px;border:0;border-radius:13px;cursor:pointer;font-weight:800}.view{color:#79445e;background:linear-gradient(115deg,#ffcce0,#ffefbe)}.unfollow{color:#a17288;background:#f9eaf1}.state-card{min-height:260px;padding:26px;display:grid;place-content:center;gap:9px;border:1px solid rgba(255,255,255,.86);border-radius:26px;color:#96677f;text-align:center;background:rgba(255,249,252,.7);backdrop-filter:blur(18px)}.big-heart{color:#db83aa;font-size:46px}@media(max-width:760px){.author-grid{grid-template-columns:1fr}}</style>
